arguments.command:
python -c "
class A:
    def __eq__(self, other):
        return NotImplemented

a = A()
print(f'a == \"foo\": {a == \"foo\"}')  # Returns False, not TypeError
try:
    result = a < 'foo'
    print(f'a < \"foo\": {result}')
except TypeError as e:
    print(f'a < \"foo\" raises TypeError: {e}')
"
